<?php
require_once __DIR__ . '/../includes/helpers.php'; verify_csrf(); $msg='';
if ($_SERVER['REQUEST_METHOD']==='POST') { $name=trim($_POST['full_name']??''); $phone=trim($_POST['phone']??''); $email=trim($_POST['email']??''); $pass=(string)($_POST['password']??''); $err=password_policy_error($pass); if(!$name||!$phone||$err){$msg=$err ?: 'Name and phone are required.';} else { $username='mem'.time(); $hash=password_hash($pass,PASSWORD_BCRYPT); $stmt=db()->prepare('INSERT INTO users (username, full_name, email, phone, password_hash, role) VALUES (?,?,?,?,?,"member")'); $stmt->bind_param('sssss',$username,$name,$email,$phone,$hash); if($stmt->execute()){ $uid=db()->insert_id; $no='OMMI-'.str_pad((string)$uid,4,'0',STR_PAD_LEFT); $stmt=db()->prepare('INSERT INTO members (user_id, member_no, full_name, phone, email, join_date) VALUES (?,?,?,?,?,CURDATE())'); $stmt->bind_param('issss',$uid,$no,$name,$phone,$email); $stmt->execute(); audit('register','member',$uid); flash('success','Registration successful. You can now login.'); redirect('login.php'); } else $msg='Account already exists or details are invalid.'; } }
?>
<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width, initial-scale=1"><title>Register</title><link rel="stylesheet" href="<?= BASE_URL ?>/assets/css/style.css"></head><body class="auth-body"><section class="auth-card"><h1>Member Registration</h1><?php if($msg): ?><div class="alert alert-danger"><?= e($msg) ?></div><?php endif; ?><form method="post"><?= csrf_field() ?><label>Full name<input name="full_name" required></label><label>Phone<input name="phone" required></label><label>Email<input type="email" name="email"></label><label>Password<input type="password" name="password" required></label><button class="btn btn-primary full">Create account</button></form><div class="auth-links"><a href="../login.php">Back to login</a></div></section></body></html>
